import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

test('bulk discount rounds the half yen up', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 11, qty: 1 }));
  assert.equal(total(lines), 105); // 110 * 0.95 = 104.5
});

// #12: the customer's discount applies once.
test('customer discount applies once below 10 lines', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900); // 1000 - 10%
});

test('customer discount, then the bulk discount once, from 10 lines', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(lines, 0.1), 8550); // 10000 - 10% = 9000, 9000 - 5% = 8550
});

// With a customer discount, fractions of a yen are dropped. Totals without a customer
// discount keep rounding the half yen up (see the tests above and the wholesale price list).
test('a discounted total drops fractions of a yen', () => {
  assert.equal(total([{ price: 995, qty: 1 }], 0.1), 895); // 995 - 99.5 = 895.5
});

test('fractions are dropped once, after both discounts', () => {
  const lines = Array.from({ length: 9 }, () => ({ price: 100, qty: 1 }));
  lines.push({ price: 102, qty: 1 });
  // 1002 - 10% = 901.8, 901.8 - 5% = 856.71 (dropping the .8 first would give 855)
  assert.equal(total(lines, 0.1), 856);
});

test('an explicit discount of 0 still rounds the half yen up', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 11, qty: 1 }));
  assert.equal(total(lines, 0), 105); // 110 * 0.95 = 104.5, same as without a discount
});

test('a discounted total that is a whole yen is not pushed down by float error', () => {
  assert.equal(total([{ price: 8650, qty: 1 }], 0.06), 8131); // 8650 - 519 = 8131 exactly
});

